 mod tests {
     use super::*;

+    const UNITS: &[(&str, u64)] = &[
+        ("b", 1),
+        ("k", KILO),
+        ("kb", KILO),
+        ("ki", KIBI),
+        ("kib", KIBI),
+        ("m", MEGA),
+        ("mb", MEGA),
+        ("mi", MEBI),
+        ("mib", MEBI),
+        ("g", GIGA),
+        ("gb", GIGA),
+        ("gi", GIBI),
+        ("gib", GIBI),
+        ("t", TERA),
+        ("tb", TERA),
+        ("ti", TEBI),
+        ("tib", TEBI),
+    ];
+
+    #[test]
+    fn rejects_size_overflow() {
+        for &(unit, multiplier) in UNITS {
+            let largest_quantity = u64::MAX / multiplier;
+            // For bytes this also tests overflow while parsing the quantity.
+            let overflowing_quantity = u128::from(largest_quantity) + 1;
+            for prefix in ["", "+", "-"] {
+                for unit in [unit.to_owned(), unit.to_uppercase()] {
+                    let input = format!("{prefix}{overflowing_quantity}{unit}");
+                    let error = SizeFilter::from_string(&input).unwrap_err();
+                    assert!(error.to_string().contains("is not a valid size constraint"));
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn preserves_size_boundaries() {
+        for &(unit, multiplier) in UNITS {
+            let largest_quantity = u64::MAX / multiplier;
+            for quantity in [0, largest_quantity] {
+                let size = quantity * multiplier;
+                for (prefix, expected) in [
+                    ("", SizeFilter::Equals(size)),
+                    ("+", SizeFilter::Min(size)),
+                    ("-", SizeFilter::Max(size)),
+                ] {
+                    let input = format!("{prefix}{quantity}{unit}");
+                    let filter = SizeFilter::from_string(&input).unwrap();
+                    assert_eq!(filter, expected, "{input}");
+                    assert!(filter.is_within(size), "{input}");
+                    if let Some(below) = size.checked_sub(1) {
+                        assert_eq!(filter.is_within(below), prefix == "-", "{input}");
+                    }
+                    if let Some(above) = size.checked_add(1) {
+                        assert_eq!(filter.is_within(above), prefix == "+", "{input}");
+                    }
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn cli_reports_size_overflow() {
+        use clap::{Parser, error::ErrorKind};
+
+        for unit in ["kb", "KiB"] {
+            for prefix in ["", "+", "-"] {
+                let input = format!("{prefix}{}{unit}", u64::MAX);
+                let error = crate::cli::Opts::try_parse_from(["fd", "--size", &input])
+                    .err()
+                    .expect("overflowing size should be rejected by the CLI");
+                assert_eq!(error.kind(), ErrorKind::ValueValidation);
+                let message = format!("'{input}' is not a valid size constraint");
+                assert!(error.to_string().contains(&message));
+            }
+        }
+    }
