+    const UNITS: [(&str, u64); 9] = [
+        ("b", 1),
+        ("k", 1_000),
+        ("m", 1_000_000),
+        ("g", 1_000_000_000),
+        ("t", 1_000_000_000_000),
+        ("ki", 1_024),
+        ("mi", 1_048_576),
+        ("gi", 1_073_741_824),
+        ("ti", 1_099_511_627_776),
+    ];
+
+    #[test]
+    fn rejects_unit_multiplication_overflow() {
+        for (unit, multiplier) in UNITS.into_iter().filter(|(_, m)| *m > 1) {
+            for quantity in [u64::MAX / multiplier + 1, u64::MAX] {
+                for prefix in ["", "+", "-"] {
+                    let input = format!("{prefix}{quantity}{unit}");
+                    assert!(SizeFilter::from_string(&input).is_err(), "{input}");
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn accepts_unit_boundaries_and_preserves_inclusive_bounds() {
+        for (unit, multiplier) in UNITS {
+            for quantity in [0, 1, u64::MAX / multiplier] {
+                let size = quantity * multiplier;
+                for (prefix, expected) in [
+                    ("", SizeFilter::Equals(size)),
+                    ("+", SizeFilter::Min(size)),
+                    ("-", SizeFilter::Max(size)),
+                ] {
+                    let input = format!("{prefix}{quantity}{unit}");
+                    let filter = SizeFilter::from_string(&input).unwrap();
+                    assert_eq!(filter, expected, "{input}");
+                    assert!(filter.is_within(size), "{input}");
+                    if size > 0 {
+                        assert_eq!(filter.is_within(size - 1), prefix == "-", "{input}");
+                    }
+                    if size < u64::MAX {
+                        assert_eq!(filter.is_within(size + 1), prefix == "+", "{input}");
+                    }
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn cli_reports_invalid_size_on_overflow() {
+        use clap::{Parser, error::ErrorKind};
+
+        use crate::cli::Opts;
+
+        for unit in ["kB", "KiB", "tB", "TiB"] {
+            for prefix in ["", "+", "-"] {
+                let input = format!("{prefix}{}{unit}", u64::MAX);
+                let error = match Opts::try_parse_from(["fd", "--size", &input]) {
+                    Err(error) => error,
+                    Ok(_) => panic!("accepted overflowing size: {input}"),
+                };
+                assert_eq!(error.kind(), ErrorKind::ValueValidation, "{input}");
+                assert!(
+                    error.to_string().contains("is not a valid size constraint"),
+                    "{error}"
+                );
+            }
+        }
+    }
