+
+/** Tests FIFO fairness without relying on real timer ticks. */
+@Timeout(30)
+class TimedSemaphoreFairnessTest {
+
+    private static final class AcquireThread extends Thread {
+        private final TimedSemaphore semaphore;
+        private final List<Integer> order;
+        private final int id;
+        private Throwable failure;
+
+        AcquireThread(final TimedSemaphore semaphore, final List<Integer> order, final int id) {
+            this.semaphore = semaphore;
+            this.order = order;
+            this.id = id;
+            setDaemon(true);
+        }
+
+        @Override
+        public void run() {
+            try {
+                synchronized (semaphore) {
+                    semaphore.acquire();
+                    order.add(id);
+                }
+            } catch (final InterruptedException | IllegalStateException ex) {
+                failure = ex;
+            }
+        }
+    }
+
+    private static void awaitWaiting(final Thread thread) throws InterruptedException {
+        final long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
+        while (thread.isAlive() && thread.getState() != Thread.State.WAITING && System.nanoTime() < deadline) {
+            Thread.sleep(1);
+        }
+        assertEquals(Thread.State.WAITING, thread.getState(), "Caller must be queued before proceeding");
+    }
+
+    private static TimedSemaphore createSemaphore(final boolean fair, final int limit) {
+        return TimedSemaphore.builder().setPeriod(1).setTimeUnit(TimeUnit.DAYS).setLimit(limit).setFair(fair).get();
+    }
+
+    private static void finish(final AcquireThread thread) throws InterruptedException {
+        thread.join(5000);
+        assertFalse(thread.isAlive(), "Acquire thread did not terminate");
+        assertNull(thread.failure);
+    }
+
+    private static AcquireThread startWaiter(final TimedSemaphore semaphore, final List<Integer> order, final int id)
+            throws InterruptedException {
+        final AcquireThread thread = new AcquireThread(semaphore, order, id);
+        thread.start();
+        awaitWaiting(thread);
+        return thread;
+    }
+
+    @Test
+    void testBuilderAndSchedulerOwnership() throws InterruptedException {
+        final ScheduledThreadPoolExecutor service = new ScheduledThreadPoolExecutor(1);
+        final TimedSemaphore semaphore = TimedSemaphore.builder().setService(service).setPeriod(2)
+                .setTimeUnit(TimeUnit.DAYS).setLimit(3).setFair(true).get();
+        try {
+            assertTrue(semaphore.isFair());
+            assertSame(service, semaphore.getExecutorService());
+            assertEquals(2L, semaphore.getPeriod());
+            assertEquals(TimeUnit.DAYS, semaphore.getUnit());
+            assertEquals(3, semaphore.getLimit());
+            assertEquals(0, service.getQueue().size());
+            semaphore.acquire();
+            assertEquals(1, service.getQueue().size());
+            semaphore.tryAcquire();
+            assertEquals(1, service.getQueue().size());
+            final ScheduledFuture<?> task = (ScheduledFuture<?>) service.getQueue().peek();
+            semaphore.shutdown();
+            assertTrue(task.isCancelled());
+            assertFalse(service.isShutdown());
+        } finally {
+            semaphore.shutdown();
+            service.shutdownNow();
+        }
+    }
+
