+            assertThrows(IllegalArgumentException.class, () -> TimedSemaphore.builder().setPeriod(-1).get());
+        } finally {
+            built.shutdown();
+            legacy.shutdown();
+            shared.shutdown();
+            service.shutdownNow();
+        }
+    }
+
+    @Test
+    void testFifoAcrossPeriodsAndAccounting() throws InterruptedException {
+        final TimedSemaphore semaphore = createSemaphore(true, 1);
+        final List<Integer> order = new ArrayList<>();
+        try {
+            semaphore.acquire();
+            final AcquireThread first = startWaiter(semaphore, order, 1);
+            final AcquireThread second = startWaiter(semaphore, order, 2);
