+        } finally {
+            semaphore.shutdown();
+        }
+    }
+
+    @Test
+    void testInterruptedWaitersAreRemoved() throws InterruptedException {
+        final TimedSemaphore semaphore = createSemaphore(true, 1);
+        final List<Integer> order = new ArrayList<>();
+        try {
+            semaphore.acquire();
+            final AcquireThread head = startWaiter(semaphore, order, 1);
+            final AcquireThread first = startWaiter(semaphore, order, 2);
+            final AcquireThread middle = startWaiter(semaphore, order, 3);
+            final AcquireThread last = startWaiter(semaphore, order, 4);
+            for (final AcquireThread interrupted : new AcquireThread[] {head, middle}) {
+                interrupted.interrupt();
+                interrupted.join(5000);
+                assertFalse(interrupted.isAlive());
+                assertTrue(interrupted.failure instanceof InterruptedException);
