+            finish(first);
+            finish(last);
+            assertEquals(Arrays.asList(2, 4), order);
+            assertEquals(3, semaphore.getAcquireCount());
+            semaphore.endOfPeriod();
+            assertEquals(3, semaphore.getLastAcquiresPerPeriod());
+            assertEquals(3.0, semaphore.getAverageCallsPerPeriod());
+        } finally {
+            semaphore.shutdown();
+        }
+    }
+
+    @Test
+    void testLimitChangesAndUnlimitedMode() throws InterruptedException {
+        for (final boolean fair : new boolean[] {false, true}) {
+            for (final int unlimited : new int[] {0, -1}) {
+                final TimedSemaphore semaphore = createSemaphore(fair, 1);
+                final List<Integer> order = new ArrayList<>();
+                try {
+                    semaphore.acquire();
+                    final AcquireThread first = startWaiter(semaphore, order, 1);
+                    semaphore.setLimit(2);
+                    finish(first);
+                    assertEquals(2, semaphore.getAcquireCount());
+                    semaphore.setLimit(1);
+                    final AcquireThread second = startWaiter(semaphore, order, 2);
+                    final AcquireThread third = startWaiter(semaphore, order, 3);
+                    synchronized (semaphore) {
+                        semaphore.setLimit(unlimited);
+                        semaphore.acquire(); // Unlimited acquire bypasses the queued callers.
+                        assertTrue(semaphore.tryAcquire());
+                    }
+                    finish(second);
+                    finish(third);
+                    assertEquals(6, semaphore.getAcquireCount());
+                    semaphore.setLimit(1);
+                    assertFalse(semaphore.tryAcquire());
+                    semaphore.endOfPeriod();
+                    assertEquals(6, semaphore.getLastAcquiresPerPeriod());
+                    assertTrue(semaphore.tryAcquire());
+                } finally {
+                    semaphore.shutdown();
+                }
+            }
+        }
+    }
+
+    @Test
+    void testShutdownWakesAllWaiters() throws InterruptedException {
+        for (final boolean fair : new boolean[] {false, true}) {
+            final TimedSemaphore semaphore = createSemaphore(fair, 1);
+            final List<Integer> order = new ArrayList<>();
+            try {
