+                .setLimit(3).setFair(true).setService(service).get();
+        try {
+            assertEquals(2, semaphore.getPeriod());
+            assertEquals(TimeUnit.DAYS, semaphore.getUnit());
+            assertEquals(3, semaphore.getLimit());
+            assertEquals(service, semaphore.getExecutorService());
+            assertTrue(service.getQueue().isEmpty());
+            semaphore.acquire();
+            assertEquals(1, service.getQueue().size());
+            semaphore.shutdown();
+            assertFalse(service.isShutdown());
+            assertThrows(IllegalStateException.class, semaphore::acquire);
+            assertThrows(IllegalStateException.class, semaphore::tryAcquire);
+        } finally {
+            semaphore.shutdown();
+            service.shutdownNow();
+        }
