+            semaphore.acquire();
+            for (int i = 0; i < 4; i++) {
+                final Waiter waiter = new Waiter(semaphore);
+                waiters.add(waiter);
+                waiter.awaitBlocked();
+            }
+            for (int i = 0; i < waiters.size(); i++) {
+                semaphore.endOfPeriod();
